    12  static int check_nwpart_address_consistency (struct ddsi_domaingv *gv)
    13  {
    14    // Each network partition needs to define at least some addresses
    15    // Any n.p. that specifies multicast addresses must have at least
    16    // one mc-capable interface
    17    struct nwpart_iter npit;
    18    nwpart_iter_init (&npit, gv);
    19    struct ddsi_config_networkpartition_listelem *np;
    20    while ((np = nwpart_iter_next (&npit)) != NULL)
    21    {
    22      if (!np->uc_addresses && !nwpart_has_multicast (np))
    23        nwpart_iter_error (&npit, "", "network partition has no addresses");
    24      else if (nwpart_has_multicast (np) && !mc_capable_ifs_used_in_nwpart (gv, np))
    25        nwpart_iter_error (&npit, "", "network partition specifies multicast addresses but no multicast-capable interfaces selected");
    26    }
    27    return nwpart_iter_fini (&npit) ? 0 : -1;
    28  }
